import type {TopicDeepening} from './topicDeepening';
type Local={fr:string;de:string;es:string};
const q=(prompt:string,choices:[string,string,string],correctIndex:number,explanation:string,evidence:Local)=>({prompt,choices,correctIndex,explanation,evidence});
const n=(explanation:string,first:string,second:string,difference:string,phrases:[string,string][])=>({explanation,first,second,difference,phrases:phrases.map(([text,meaning])=>({text,meaning}))});
/** Original fictional lessons for individual syllabus topics. */
export const topicDeepeningContinue:readonly TopicDeepening[]=[
{id:'b1-negotiate-meeting',level:'b1',section:'survival',number:10,title:'مذاکره برای زمان دیدار',passage:{
fr:'Mina et Lucas doivent rencontrer trois bénévoles pour préparer un atelier. Mina propose mardi à dix-sept heures, mais Lucas travaille jusqu’à dix-huit heures ce jour-là. Lucas suggère mercredi à midi. Mina explique qu’elle a un rendez-vous médical mercredi, mais qu’elle est libre jeudi après seize heures. Ils consultent ensuite les bénévoles : deux personnes peuvent venir jeudi à dix-sept heures, tandis que la troisième ne peut participer que par téléphone. Mina propose de réserver une salle calme et d’appeler cette personne au début. Tous acceptent cette solution. Lucas enverra l’adresse et Mina vérifiera que le téléphone de la salle fonctionne.',
de:'Mina und Lucas müssen drei Freiwillige treffen, um einen Workshop vorzubereiten. Mina schlägt Dienstag um siebzehn Uhr vor, aber Lucas arbeitet an diesem Tag bis achtzehn Uhr. Lucas schlägt Mittwochmittag vor. Mina erklärt, dass sie am Mittwoch einen Arzttermin hat, aber am Donnerstag nach sechzehn Uhr frei ist. Dann fragen sie die Freiwilligen: Zwei Personen können am Donnerstag um siebzehn Uhr kommen, während die dritte nur telefonisch teilnehmen kann. Mina schlägt vor, einen ruhigen Raum zu reservieren und diese Person am Anfang anzurufen. Alle akzeptieren die Lösung. Lucas schickt die Adresse und Mina prüft, ob das Telefon im Raum funktioniert.',
es:'Mina y Lucas tienen que reunirse con tres voluntarios para preparar un taller. Mina propone el martes a las cinco, pero Lucas trabaja hasta las seis ese día. Lucas sugiere el miércoles al mediodía. Mina explica que tiene una cita médica el miércoles, pero está libre el jueves después de las cuatro. Después consultan a los voluntarios: dos personas pueden venir el jueves a las cinco, mientras que la tercera solo puede participar por teléfono. Mina propone reservar una sala tranquila y llamar a esa persona al principio. Todos aceptan la solución. Lucas enviará la dirección y Mina comprobará que el teléfono de la sala funciona.'},
questions:[q('چرا زمان سه‌شنبه برای لوکاس مناسب نیست؟',['او تا ساعت هجده کار می‌کند','اتاق سه‌شنبه بسته است','او در سفر است'],0,'او سه‌شنبه تا هجده کار می‌کند.',{fr:'Lucas travaille jusqu’à dix-huit heures ce jour-là',de:'Lucas arbeitet an diesem Tag bis achtzehn Uhr',es:'Lucas trabaja hasta las seis ese día'}),q('نفر سوم چگونه می‌تواند شرکت کند؟',['فقط با ارسال نامه','فقط تلفنی','فقط روز سه‌شنبه'],1,'او فقط می‌تواند تلفنی شرکت کند.',{fr:'la troisième ne peut participer que par téléphone',de:'die dritte nur telefonisch teilnehmen kann',es:'la tercera solo puede participar por teléfono'}),q('پس از توافق چه کسی نشانی را می‌فرستد؟',['مینا','نفر تلفنی','لوکاس'],2,'لوکاس نشانی را می‌فرستد.',{fr:'Lucas enverra l’adresse',de:'Lucas schickt die Adresse',es:'Lucas enviará la dirección'})],
notes:{fr:n('برای پیشنهاد «je propose de» و برای بیان محدودیت «je ne peux pas» به کار ببرید؛ توافق را با زمان و مسئولیت خلاصه کنید.','Je propose de nous rencontrer jeudi.','Je ne peux pas venir mardi avant dix-huit heures.','اولی پیشنهاد و دومی محدودیت زمانی است.',[['proposer un horaire','پیشنهاد زمان'],['participer par téléphone','شرکت تلفنی'],['réserver une salle','رزرو اتاق']]),de:n('«ich schlage … vor» پیشنهاد و «ich kann nicht» محدودیت را بیان می‌کند؛ در پایان زمان و مسئولیت‌ها را تأیید کنید.','Ich schlage vor, dass wir uns am Donnerstag treffen.','Ich kann am Dienstag nicht vor achtzehn Uhr kommen.','اولی پیشنهاد و دومی محدودیت زمانی است.',[['eine Uhrzeit vorschlagen','پیشنهاد زمان'],['telefonisch teilnehmen','شرکت تلفنی'],['einen Raum reservieren','رزرو اتاق']]),es:n('با «propongo» پیشنهاد و با «no puedo» محدودیت را بیان کنید؛ زمان توافق و مسئولیت‌ها را خلاصه کنید.','Propongo reunirnos el jueves.','No puedo venir el martes antes de las seis.','اولی پیشنهاد و دومی محدودیت زمانی است.',[['proponer un horario','پیشنهاد زمان'],['participar por teléfono','شرکت تلفنی'],['reservar una sala','رزرو اتاق']])},
speaking:'برای جلسه‌ای فرضی زمانی پیشنهاد کنید، به محدودیت همکارتان پاسخ دهید و راه شرکت فردی از راه دور را توافق کنید.',writing:'پیام تأییدی بنویسید که زمان، محل، شرکت تلفنی و مسئول هر کار را روشن کند.',steps:['زمان مورد توافق را بنویسید.','محل و روش شرکت فرد غایب را بیان کنید.','مسئول ارسال نشانی و بررسی تلفن را مشخص کنید.','از دیگران تأیید بخواهید.'],model:{fr:'Bonjour, nous nous retrouverons jeudi à dix-sept heures pour préparer l’atelier. Deux bénévoles seront présents dans la salle et nous appellerons la troisième personne au début. Lucas enverra l’adresse et je vérifierai le téléphone de la salle. Merci de confirmer que cet horaire vous convient. À jeudi !',de:'Hallo, wir treffen uns am Donnerstag um siebzehn Uhr, um den Workshop vorzubereiten. Zwei Freiwillige kommen in den Raum, und wir rufen die dritte Person zu Beginn an. Lucas schickt die Adresse und ich prüfe das Telefon im Raum. Bitte bestätigt, dass die Uhrzeit für euch passt. Bis Donnerstag!',es:'Hola, nos reuniremos el jueves a las cinco para preparar el taller. Dos voluntarios vendrán a la sala y llamaremos a la tercera persona al principio. Lucas enviará la dirección y yo comprobaré el teléfono de la sala. Confirmad, por favor, que el horario os conviene. ¡Hasta el jueves!'}},
{id:'b1-story-lost-bag',level:'b1',section:'survival',number:18,title:'بازگویی یک اتفاق غیرمنتظره',passage:{
fr:'Samedi dernier, Omar voyageait en train pour rendre visite à sa sœur. En descendant à la gare, il a remarqué qu’il avait oublié son sac sous son siège. Le train était déjà reparti. Il est allé au bureau des objets trouvés et a expliqué que son sac bleu contenait un livre et un chargeur, mais aucun document important. L’employée a appelé la gare suivante et lui a demandé de laisser son numéro. Une heure plus tard, elle l’a rappelé : le sac avait été retrouvé par le personnel du train. Omar a pu le récupérer le lendemain. Depuis, il vérifie toujours son siège avant de descendre.',
de:'Am letzten Samstag fuhr Omar mit dem Zug zu seiner Schwester. Als er am Bahnhof ausstieg, bemerkte er, dass er seine Tasche unter dem Sitz vergessen hatte. Der Zug war bereits weitergefahren. Er ging zum Fundbüro und erklärte, dass seine blaue Tasche ein Buch und ein Ladegerät, aber keine wichtigen Dokumente enthielt. Die Mitarbeiterin rief den nächsten Bahnhof an und bat ihn, seine Nummer zu hinterlassen. Eine Stunde später rief sie zurück: Das Zugpersonal hatte die Tasche gefunden. Omar konnte sie am nächsten Tag abholen. Seitdem kontrolliert er seinen Sitz immer, bevor er aussteigt.',
es:'El sábado pasado, Omar viajaba en tren para visitar a su hermana. Al bajar en la estación, se dio cuenta de que había olvidado la bolsa debajo del asiento. El tren ya había salido. Fue a la oficina de objetos perdidos y explicó que su bolsa azul contenía un libro y un cargador, pero ningún documento importante. La empleada llamó a la siguiente estación y le pidió que dejara su número. Una hora más tarde volvió a llamarlo: el personal del tren había encontrado la bolsa. Omar pudo recogerla al día siguiente. Desde entonces siempre revisa su asiento antes de bajar.'},
questions:[q('عمر کجا متوجه گم شدن کیف شد؟',['پس از پیاده شدن در ایستگاه','در خانهٔ خواهرش','در فرودگاه'],0,'او پس از پیاده شدن متوجه شد.',{fr:'En descendant à la gare, il a remarqué',de:'Als er am Bahnhof ausstieg, bemerkte er',es:'Al bajar en la estación, se dio cuenta'}),q('در کیف چه چیزهایی بود؟',['مدارک مهم و پول','کتاب و شارژر بدون مدارک مهم','فقط لباس'],1,'کیف حاوی کتاب و شارژر بود و مدرک مهمی نداشت.',{fr:'un livre et un chargeur, mais aucun document important',de:'ein Buch und ein Ladegerät, aber keine wichtigen Dokumente',es:'un libro y un cargador, pero ningún documento importante'}),q('کیف چه زمانی به دست عمر رسید؟',['همان لحظه','یک هفته بعد','روز بعد'],2,'او روز بعد کیف را تحویل گرفت.',{fr:'récupérer le lendemain',de:'am nächsten Tag abholen',es:'recogerla al día siguiente'})],
notes:{fr:n('در روایت اتفاق زمینه، رخداد پیشین و نتیجه را با زمان و رابط روشن کنید؛ plus-que-parfait می‌تواند رخداد پیش از رویداد دیگر را نشان دهد.','Il voyageait en train quand il a remarqué la disparition.','Il avait oublié son sac sous le siège.','اولی زمینه و رویداد اصلی و دومی اتفاق پیشین است.',[['un objet trouvé','شیء پیدا شده'],['laisser son numéro','شمارهٔ تماس گذاشتن'],['récupérer un sac','تحویل گرفتن کیف']]),de:n('برای بیان رویدادی پیش از رویداد گذشته از Plusquamperfekt استفاده کنید و ترتیب را با زمان‌ها یا قیدها روشن کنید.','Er bemerkte das Problem am Bahnhof.','Er hatte die Tasche unter dem Sitz vergessen.','اولی لحظهٔ متوجه شدن و دومی اتفاق پیشین است.',[['das Fundbüro','دفتر اشیای گمشده'],['eine Nummer hinterlassen','شمارهٔ تماس گذاشتن'],['eine Tasche abholen','تحویل گرفتن کیف']]),es:n('برای رویدادی پیش از رویداد گذشته می‌توان pluscuamperfecto به کار برد؛ imperfecto زمینهٔ در حال جریان را می‌سازد.','Viajaba en tren cuando se dio cuenta del problema.','Había olvidado la bolsa debajo del asiento.','اولی زمینه و رویداد اصلی و دومی اتفاق پیشین است.',[['objetos perdidos','اشیای گمشده'],['dejar el número','شمارهٔ تماس گذاشتن'],['recoger una bolsa','تحویل گرفتن کیف']])},
speaking:'داستانی با زمینه، اتفاقی پیش از رخداد اصلی، اقدام برای حل مشکل و نتیجه را تعریف کنید.',writing:'به دوستی پیام بدهید و داستان کیف گمشده را به ترتیب با نتیجه و درسی که گرفتید بازگو کنید.',steps:['زمان، مکان و زمینه را معرفی کنید.','اتفاق پیشین و لحظهٔ متوجه شدن را جدا کنید.','اقدام پیگیری و پاسخ را شرح دهید.','نتیجه و عادت تازه را اضافه کنید.'],model:{fr:'Samedi, je voyageais en train quand j’ai remarqué que j’avais oublié mon sac sous le siège. Le train était déjà parti. Au bureau des objets trouvés, j’ai expliqué ce qu’il contenait et laissé mon numéro. Une heure plus tard, l’employée m’a dit que le personnel l’avait retrouvé. Je l’ai récupéré le lendemain et je vérifie maintenant mon siège avant de descendre.',de:'Am Samstag fuhr ich mit dem Zug, als ich bemerkte, dass ich meine Tasche unter dem Sitz vergessen hatte. Der Zug war schon weitergefahren. Im Fundbüro erklärte ich den Inhalt und hinterließ meine Nummer. Eine Stunde später sagte die Mitarbeiterin, dass das Zugpersonal die Tasche gefunden hatte. Ich holte sie am nächsten Tag ab und kontrolliere seitdem meinen Sitz vor dem Aussteigen.',es:'El sábado viajaba en tren cuando me di cuenta de que había olvidado mi bolsa debajo del asiento. El tren ya había salido. En objetos perdidos expliqué el contenido y dejé mi número. Una hora después, la empleada me dijo que el personal había encontrado la bolsa. La recogí al día siguiente y desde entonces reviso mi asiento antes de bajar.'}},
{id:'b1-culture-differences',level:'b1',section:'survival',number:22,title:'گفت‌وگو دربارهٔ عادت‌های خانوادگی',passage:{
fr:'Dans un groupe de conversation, Elena raconte que sa famille prépare souvent un grand repas le dimanche. Son ami Farid explique que, dans sa famille, les horaires de travail sont différents et que le repas commun a plutôt lieu le vendredi soir. Elena lui demande qui choisit le menu. Farid répond que chacun propose un plat et qu’ils décident ensemble. Une autre participante remarque que les habitudes peuvent varier même entre familles d’une même ville. Le groupe partage ensuite des idées de recettes sans supposer qu’une seule habitude représente tous les habitants d’un pays. Ils conviennent de cuisiner ensemble le mois suivant.',
de:'In einer Gesprächsgruppe erzählt Elena, dass ihre Familie sonntags oft ein großes Essen vorbereitet. Ihr Freund Farid erklärt, dass die Arbeitszeiten in seiner Familie unterschiedlich sind und das gemeinsame Essen eher am Freitagabend stattfindet. Elena fragt ihn, wer das Menü auswählt. Farid antwortet, dass jede Person ein Gericht vorschlägt und sie gemeinsam entscheiden. Eine weitere Teilnehmerin bemerkt, dass Gewohnheiten sogar zwischen Familien derselben Stadt unterschiedlich sein können. Danach teilt die Gruppe Rezeptideen, ohne anzunehmen, dass eine einzelne Gewohnheit alle Menschen eines Landes repräsentiert. Sie vereinbaren, im nächsten Monat zusammen zu kochen.',
es:'En un grupo de conversación, Elena cuenta que su familia suele preparar una comida grande los domingos. Su amigo Farid explica que en su familia los horarios de trabajo son diferentes y que la comida común suele ser el viernes por la noche. Elena le pregunta quién elige el menú. Farid responde que cada persona propone un plato y que deciden juntos. Otra participante observa que las costumbres pueden variar incluso entre familias de una misma ciudad. Después el grupo comparte ideas de recetas sin suponer que una sola costumbre representa a todos los habitantes de un país. Acuerdan cocinar juntos el mes siguiente.'},
questions:[q('خانوادهٔ النا معمولاً چه روزی غذای مشترک دارند؟',['یکشنبه','چهارشنبه','شنبه'],0,'او از غذای یکشنبه صحبت می‌کند.',{fr:'un grand repas le dimanche',de:'sonntags oft ein großes Essen',es:'una comida grande los domingos'}),q('در خانوادهٔ فرید منو چگونه انتخاب می‌شود؟',['فقط یک نفر انتخاب می‌کند','هر نفر پیشنهادی می‌دهد و با هم تصمیم می‌گیرند','فقط رستوران تصمیم می‌گیرد'],1,'هر فرد پیشنهادی می‌دهد و تصمیم مشترک است.',{fr:'chacun propose un plat et qu’ils décident ensemble',de:'jede Person ein Gericht vorschlägt und sie gemeinsam entscheiden',es:'cada persona propone un plato y que deciden juntos'}),q('گروه دربارهٔ تفاوت عادت‌ها چه نکته‌ای را می‌پذیرد؟',['همهٔ خانواده‌ها یکسان‌اند','یک رسم نمایندهٔ همهٔ کشور است','عادت‌ها حتی در یک شهر ممکن است متفاوت باشند'],2,'عادت‌ها ممکن است میان خانواده‌های یک شهر تفاوت داشته باشند.',{fr:'varier même entre familles d’une même ville',de:'zwischen Familien derselben Stadt unterschiedlich sein können',es:'variar incluso entre familias de una misma ciudad'})],
notes:{fr:n('برای صحبت محترمانه از «dans ma famille» استفاده کنید و تجربهٔ یک فرد را به همه تعمیم ندهید؛ پرسش باز ادامهٔ گفت‌وگو را آسان می‌کند.','Dans ma famille, nous mangeons souvent ensemble le dimanche.','Et chez toi, qui choisit le menu ?', 'اولی تجربهٔ شخصی و دومی پرسش باز است.',[['un repas familial','غذای خانوادگی'],['choisir le menu','انتخاب منو'],['partager une recette','به اشتراک گذاشتن دستور']]),de:n('با «in meiner Familie» تجربهٔ شخصی را از تعمیم دربارهٔ همه جدا کنید و با پرسشی باز گفت‌وگو را ادامه دهید.','In meiner Familie essen wir sonntags oft zusammen.','Und bei dir, wer wählt das Menü aus?','اولی تجربهٔ شخصی و دومی پرسش باز است.',[['ein Familienessen','غذای خانوادگی'],['das Menü auswählen','انتخاب منو'],['ein Rezept teilen','به اشتراک گذاشتن دستور']]),es:n('با «en mi familia» تجربهٔ شخصی را محدود کنید و با پرسش باز از رسم فرد مقابل آگاه شوید، بدون تعمیم به همه.','En mi familia comemos juntos los domingos.','Y en tu casa, ¿quién elige el menú?','اولی تجربهٔ شخصی و دومی پرسش باز است.',[['una comida familiar','غذای خانوادگی'],['elegir el menú','انتخاب منو'],['compartir una receta','به اشتراک گذاشتن دستور']])},
speaking:'یک عادت خانوادهٔ خود یا فرضی را توضیح دهید، دربارهٔ تجربهٔ دیگری سؤال کنید و از تعمیم پرهیز کنید.',writing:'پیامی به هم‌گروهی بنویسید که یک تجربه، یک تفاوت محترمانه و پرسشی باز برای او داشته باشد.',steps:['یک تجربهٔ شخصی و زمان آن را بیان کنید.','تفاوت احتمالی را با احترام توضیح دهید.','دربارهٔ تجربهٔ مخاطب سؤال باز بپرسید.','از نسبت دادن یک رسم به همه پرهیز کنید.'],model:{fr:'Dans ma famille, nous préparons souvent un repas ensemble le dimanche. Chacun propose un plat et nous choisissons le menu ensemble. Je sais que les horaires et les habitudes peuvent être différents selon les familles. Et chez toi, quand peux-tu partager un repas avec tes proches ? J’aimerais aussi découvrir une recette que tu apprécies.',de:'In meiner Familie bereiten wir sonntags oft gemeinsam ein Essen vor. Jede Person schlägt ein Gericht vor und wir wählen das Menü zusammen. Ich weiß, dass Zeiten und Gewohnheiten von Familie zu Familie unterschiedlich sein können. Und bei dir, wann kannst du mit deinen Angehörigen essen? Ich würde auch gern ein Rezept kennenlernen, das du magst.',es:'En mi familia solemos preparar una comida juntos los domingos. Cada persona propone un plato y elegimos el menú entre todos. Sé que los horarios y las costumbres pueden ser diferentes según la familia. ¿Y en tu casa, cuándo puedes compartir una comida con tus familiares? También me gustaría conocer una receta que te guste.'}},
{id:'b2-persuade-evidence',level:'b2',section:'survival',number:21,title:'متقاعدسازی با دلیل و شواهد محدود',passage:{
fr:'Un groupe propose d’installer des fontaines à eau dans un centre sportif. Pendant un mois, il a demandé à quatre-vingts visiteurs comment ils apportaient leur eau. Cinquante ont dit acheter au moins une bouteille sur place ; cette réponse ne mesure toutefois pas le nombre total de bouteilles utilisées. Les responsables estiment que deux fontaines pourraient réduire certains achats, mais ils ne connaissent pas encore le coût annuel de maintenance. Une représentante demande donc un devis et propose un essai de trois mois. Pour convaincre le conseil, le groupe présentera les réponses, reconnaîtra leurs limites et comparera le coût de l’essai avec les données de ventes disponibles.',
de:'Eine Gruppe schlägt vor, in einem Sportzentrum Trinkwasserstationen einzurichten. Einen Monat lang fragte sie achtzig Besucher, wie sie ihr Wasser mitbringen. Fünfzig sagten, dass sie vor Ort mindestens eine Flasche kaufen; diese Antwort misst jedoch nicht die Gesamtzahl der verwendeten Flaschen. Die Verantwortlichen schätzen, dass zwei Stationen einige Käufe reduzieren könnten, kennen aber die jährlichen Wartungskosten noch nicht. Eine Vertreterin bittet deshalb um einen Kostenvoranschlag und schlägt einen dreimonatigen Test vor. Um den Rat zu überzeugen, wird die Gruppe die Antworten und ihre Grenzen vorstellen und die Testkosten mit verfügbaren Verkaufsdaten vergleichen.',
es:'Un grupo propone instalar fuentes de agua en un centro deportivo. Durante un mes preguntó a ochenta visitantes cómo llevaban su agua. Cincuenta dijeron que compraban al menos una botella en el centro; sin embargo, esa respuesta no mide el número total de botellas utilizadas. Los responsables creen que dos fuentes podrían reducir algunas compras, pero aún no conocen el coste anual de mantenimiento. Por eso una representante pide un presupuesto y propone una prueba de tres meses. Para convencer al consejo, el grupo presentará las respuestas, reconocerá sus límites y comparará el coste de la prueba con los datos de ventas disponibles.'},
questions:[q('چند نفر گفتند حداقل یک بطری در مرکز می‌خرند؟',['پنجاه نفر','هشتاد نفر','دو نفر'],0,'پنجاه نفر چنین پاسخی دادند.',{fr:'Cinquante ont dit acheter au moins une bouteille',de:'Fünfzig sagten, dass sie vor Ort mindestens eine Flasche kaufen',es:'Cincuenta dijeron que compraban al menos una botella'}),q('محدودیت پرسش‌نامه چیست؟',['هیچ بازدیدکننده‌ای پاسخ نداده','تعداد کل بطری‌های استفاده‌شده را اندازه نمی‌گیرد','هزینهٔ سالانه را دقیق ثابت می‌کند'],1,'پاسخ تعداد کل بطری‌ها را اندازه نمی‌گیرد.',{fr:'ne mesure toutefois pas le nombre total de bouteilles utilisées',de:'misst jedoch nicht die Gesamtzahl der verwendeten Flaschen',es:'no mide el número total de botellas utilizadas'}),q('برای تصمیم چه اقدامی پیشنهاد شده است؟',['اجرای دائمی بدون هزینه','حذف همهٔ داده‌ها','برآورد هزینه و آزمایش سه‌ماهه'],2,'برآورد و آزمایش سه‌ماهه پیشنهاد شده‌اند.',{fr:'un devis et propose un essai de trois mois',de:'um einen Kostenvoranschlag und schlägt einen dreimonatigen Test vor',es:'un presupuesto y propone una prueba de tres meses'})],
notes:{fr:n('در متقاعدسازی، ادعا را با دادهٔ دقیق و محدودیت آن همراه کنید؛ «pourrait» نتیجهٔ احتمالی را بدون وعدهٔ قطعی نشان می‌دهد.','Deux fontaines pourraient réduire certains achats.','Cependant, nous ne connaissons pas le coût annuel.','اولی ادعای مشروط و دومی محدودیت اطلاعات است.',[['une fontaine à eau','آب‌سردکن'],['un coût de maintenance','هزینهٔ نگهداری'],['des données de ventes','دادهٔ فروش']]),de:n('برای متقاعدسازی ادعا، شاهد و محدودیت را جدا کنید؛ «könnten» نتیجهٔ احتمالی و نه تضمین را نشان می‌دهد.','Zwei Stationen könnten einige Käufe reduzieren.','Die jährlichen Wartungskosten sind jedoch unbekannt.','اولی ادعای مشروط و دومی محدودیت اطلاعات است.',[['eine Trinkwasserstation','آب‌سردکن'],['Wartungskosten','هزینهٔ نگهداری'],['Verkaufsdaten','دادهٔ فروش']]),es:n('برای متقاعدسازی از دادهٔ دقیق همراه محدودیت استفاده کنید؛ condicional نتیجهٔ احتمالی را بدون قطعیت نشان می‌دهد.','Dos fuentes podrían reducir algunas compras.','Sin embargo, desconocemos el coste anual.','اولی ادعای مشروط و دومی محدودیت اطلاعات است.',[['una fuente de agua','آب‌سردکن'],['el coste de mantenimiento','هزینهٔ نگهداری'],['datos de ventas','دادهٔ فروش']])},
speaking:'از آزمایش آب‌سردکن دفاع کنید؛ دادهٔ موجود، محدودیت آن، هزینهٔ نامعلوم و روش بررسی را بیان کنید.',writing:'پیشنهادی اقناعی برای شورا بنویسید که ادعا، شواهد محدود، اعتراض دربارهٔ هزینه و آزمایش را شامل شود.',steps:['پیشنهاد و دلیل آن را معرفی کنید.','پاسخ‌های پرسش‌نامه را دقیق و بدون تعمیم گزارش کنید.','محدودیت داده و هزینهٔ نامعلوم را بپذیرید.','آزمایش و مقایسهٔ داده‌ها را پیشنهاد دهید.'],model:{fr:'Nous proposons un essai de trois mois avec deux fontaines. Sur quatre-vingts visiteurs interrogés, cinquante ont dit acheter au moins une bouteille sur place. Ce chiffre ne mesure pas toutes les bouteilles utilisées ; nous ne pouvons donc pas garantir une réduction précise. Demandons un devis de maintenance et comparons les coûts de l’essai aux données de ventes disponibles avant une décision permanente.',de:'Wir schlagen einen dreimonatigen Test mit zwei Trinkwasserstationen vor. Von achtzig Befragten sagten fünfzig, dass sie vor Ort mindestens eine Flasche kaufen. Diese Zahl misst nicht alle verwendeten Flaschen; eine genaue Verringerung können wir daher nicht garantieren. Wir sollten einen Wartungskostenvoranschlag einholen und die Testkosten mit verfügbaren Verkaufsdaten vergleichen, bevor wir dauerhaft entscheiden.',es:'Proponemos una prueba de tres meses con dos fuentes. De ochenta visitantes consultados, cincuenta dijeron que compraban al menos una botella en el centro. Esta cifra no mide todas las botellas utilizadas, por lo que no podemos garantizar una reducción exacta. Pidamos un presupuesto de mantenimiento y comparemos el coste de la prueba con los datos de ventas disponibles antes de decidir de forma permanente.'}},
{id:'b2-scenario-alternatives',level:'b2',section:'survival',number:23,title:'مقایسهٔ سناریوهای جایگزین',passage:{
fr:'Une association prépare une réunion publique au sujet d’un parc. Elle étudie deux scénarios. Si la salle municipale est disponible, la réunion se tiendra en personne et les habitants pourront consulter les plans sur place. Si elle ne l’est pas, l’association organisera une réunion en ligne avec une ligne téléphonique pour les personnes sans ordinateur. Dans ce second cas, les plans devront être envoyés à l’avance. La responsable rappelle qu’aucune réservation n’est encore confirmée et que la connexion en ligne doit être testée. L’équipe vérifiera la salle lundi et choisira un scénario après avoir reçu les réponses des habitants sur leurs besoins d’accès.',
de:'Ein Verein bereitet eine öffentliche Sitzung zu einem Park vor und prüft zwei Szenarien. Wenn der städtische Raum verfügbar ist, findet die Sitzung vor Ort statt und die Einwohner können die Pläne dort ansehen. Falls er nicht verfügbar ist, organisiert der Verein eine Online-Sitzung mit einer Telefonleitung für Menschen ohne Computer. In diesem zweiten Fall müssen die Pläne vorher verschickt werden. Die Leiterin erinnert daran, dass noch keine Reservierung bestätigt ist und die Online-Verbindung getestet werden muss. Das Team prüft am Montag den Raum und wählt ein Szenario, nachdem es die Antworten der Einwohner zu ihren Zugangsmöglichkeiten erhalten hat.',
es:'Una asociación prepara una reunión pública sobre un parque y estudia dos escenarios. Si la sala municipal está disponible, la reunión será presencial y los vecinos podrán consultar los planos allí. Si no lo está, la asociación organizará una reunión en línea con una línea telefónica para quienes no tengan ordenador. En ese segundo caso, habrá que enviar los planos con antelación. La responsable recuerda que todavía no se ha confirmado ninguna reserva y que es necesario probar la conexión en línea. El equipo comprobará la sala el lunes y elegirá un escenario después de recibir las respuestas de los vecinos sobre sus necesidades de acceso.'},
questions:[q('اگر سالن شهری در دسترس باشد چه می‌شود؟',['جلسه حضوری و مشاهدهٔ نقشه در محل','جلسه بدون نقشه لغو می‌شود','همه باید تلفنی شرکت کنند'],0,'در صورت دسترسی، جلسه حضوری خواهد بود.',{fr:'la réunion se tiendra en personne',de:'findet die Sitzung vor Ort statt',es:'la reunión será presencial'}),q('در سناریوی آنلاین برای افراد بدون رایانه چه پیش‌بینی شده است؟',['حذف امکان مشارکت','خط تلفن','فقط ارسال نامه پس از جلسه'],1,'خط تلفن پیش‌بینی شده است.',{fr:'une ligne téléphonique pour les personnes sans ordinateur',de:'einer Telefonleitung für Menschen ohne Computer',es:'una línea telefónica para quienes no tengan ordenador'}),q('پیش از انتخاب نهایی چه چیزی بررسی می‌شود؟',['فقط رنگ صندلی','تاریخ جلسهٔ سال گذشته','دسترسی سالن و نیازهای مشارکت ساکنان'],2,'تیم وضعیت سالن و نیازهای دسترسی را بررسی می‌کند.',{fr:'vérifiera la salle lundi et choisira un scénario après avoir reçu les réponses',de:'prüft am Montag den Raum und wählt ein Szenario, nachdem es die Antworten',es:'comprobará la sala el lunes y elegirá un escenario después de recibir las respuestas'})],
notes:{fr:n('سناریوها را با شرط، پیامد و اقدام لازم جدا کنید؛ اگر وضعیت قطعی نیست با «si» و بیان عدم تأیید از ادعای واقعیت بپرهیزید.','Si la salle est disponible, nous nous réunirons sur place.','Sinon, nous organiserons une réunion en ligne avec une ligne téléphonique.','اولی شرط حضوری و دومی راه جایگزین است.',[['une salle disponible','سالن در دسترس'],['une ligne téléphonique','خط تلفن'],['envoyer à l’avance','ارسال از پیش']]),de:n('شرط را با «wenn/falls» و گزینهٔ جایگزین را با «andernfalls» بیان کنید؛ دسترسی و وضعیت تأیید را روشن نگه دارید.','Wenn der Raum verfügbar ist, treffen wir uns vor Ort.','Andernfalls organisieren wir eine Online-Sitzung mit Telefonleitung.','اولی شرط حضوری و دومی راه جایگزین است.',[['ein verfügbarer Raum','سالن در دسترس'],['eine Telefonleitung','خط تلفن'],['vorher verschicken','ارسال از پیش']]),es:n('با «si» شرط واقعی و با «si no» یا «de lo contrario» گزینهٔ جایگزین را معرفی کنید؛ رزرو نامعلوم را قطعی اعلام نکنید.','Si la sala está disponible, nos reuniremos allí.','Si no, organizaremos una reunión en línea con teléfono.','اولی شرط حضوری و دومی راه جایگزین است.',[['una sala disponible','سالن در دسترس'],['una línea telefónica','خط تلفن'],['enviar con antelación','ارسال از پیش']])},
speaking:'دو سناریو را با شرط، پیامد، نیاز دسترسی و اطلاعات لازم برای تصمیم مقایسه کنید.',writing:'به ساکنان پیام بدهید و هر دو گزینه، وضعیت نامعلوم و زمان انتخاب را توضیح دهید.',steps:['موضوع و دو سناریو را معرفی کنید.','شرط و اقدام هر سناریو را روشن کنید.','دسترسی تلفنی و ارسال نقشه را بیان کنید.','اطلاعات نامعلوم و زمان بررسی را اضافه کنید.'],model:{fr:'Nous préparons une réunion sur le parc. Si la salle municipale est disponible, nous nous rencontrerons sur place et les plans y seront consultables. Sinon, nous organiserons une réunion en ligne avec une ligne téléphonique et enverrons les plans à l’avance. Aucune réservation n’est encore confirmée. Nous vérifierons la salle lundi et tiendrons compte de vos besoins d’accès avant de choisir.',de:'Wir bereiten eine Sitzung zum Park vor. Wenn der städtische Raum verfügbar ist, treffen wir uns vor Ort und die Pläne liegen dort aus. Andernfalls organisieren wir eine Online-Sitzung mit Telefonleitung und verschicken die Pläne vorher. Eine Reservierung ist noch nicht bestätigt. Wir prüfen den Raum am Montag und berücksichtigen Ihre Zugangsmöglichkeiten vor der Entscheidung.',es:'Preparamos una reunión sobre el parque. Si la sala municipal está disponible, nos reuniremos allí y podrán consultar los planos. Si no, organizaremos una reunión en línea con teléfono y enviaremos los planos con antelación. Todavía no hay una reserva confirmada. Comprobaremos la sala el lunes y tendremos en cuenta sus necesidades de acceso antes de elegir.'}},
{id:'b2-unexpected-interruption',level:'b2',section:'survival',number:27,title:'مدیریت اختلال پیش‌بینی‌نشده در ارائه',passage:{
fr:'Pendant une présentation en ligne, la connexion de l’interprète s’interrompt. La responsable interrompt la présentation et explique aux participants que certaines personnes ne peuvent plus suivre dans leur langue. Elle demande à l’équipe technique de vérifier la connexion et annonce une pause de cinq minutes, sans promettre que le problème sera résolu immédiatement. Une collègue propose d’envoyer le plan écrit dans les deux langues pendant l’attente. Lorsque la connexion revient, la responsable résume le dernier point et demande aux participants s’ils ont reçu le document. Elle convient ensuite avec l’interprète d’un signal pour interrompre à nouveau si nécessaire.',
de:'Während einer Online-Präsentation bricht die Verbindung der Dolmetscherin ab. Die Leiterin unterbricht den Vortrag und erklärt den Teilnehmenden, dass einige Menschen in ihrer Sprache nicht mehr folgen können. Sie bittet das technische Team, die Verbindung zu prüfen, und kündigt eine Pause von fünf Minuten an, ohne eine sofortige Lösung zu versprechen. Eine Kollegin schlägt vor, während der Wartezeit die schriftliche Gliederung in beiden Sprachen zu verschicken. Als die Verbindung zurückkommt, fasst die Leiterin den letzten Punkt zusammen und fragt, ob die Teilnehmenden das Dokument erhalten haben. Danach vereinbart sie mit der Dolmetscherin ein Signal für eine erneute Unterbrechung, falls nötig.',
es:'Durante una presentación en línea se interrumpe la conexión de la intérprete. La responsable detiene la presentación y explica a los participantes que algunas personas ya no pueden seguirla en su idioma. Pide al equipo técnico que compruebe la conexión y anuncia una pausa de cinco minutos, sin prometer que el problema se resolverá de inmediato. Una compañera propone enviar el esquema escrito en ambos idiomas mientras esperan. Cuando vuelve la conexión, la responsable resume el último punto y pregunta si los participantes han recibido el documento. Después acuerda con la intérprete una señal para volver a interrumpir si es necesario.'},
questions:[q('اختلال اصلی چیست؟',['قطع اتصال مترجم شفاهی','لغو سالن حضوری','نبود اسلاید مالی'],0,'اتصال مترجم قطع می‌شود.',{fr:'la connexion de l’interprète s’interrompt',de:'die Verbindung der Dolmetscherin ab',es:'se interrumpe la conexión de la intérprete'}),q('مسئول چگونه زمان انتظار را اعلام می‌کند؟',['حل قطعی فوری را قول می‌دهد','پنج دقیقه وقفه اعلام می‌کند بدون وعدهٔ حل فوری','بدون توضیح جلسه را می‌بندد'],1,'او وقفه اعلام می‌کند ولی وعدهٔ حل فوری نمی‌دهد.',{fr:'une pause de cinq minutes, sans promettre',de:'eine Pause von fünf Minuten an, ohne eine sofortige Lösung zu versprechen',es:'una pausa de cinco minutos, sin prometer'}),q('پس از بازگشت اتصال چه اتفاقی می‌افتد؟',['موضوع قبلی حذف می‌شود','تفسیر بدون هماهنگی قطع می‌شود','نکتهٔ آخر خلاصه و دریافت سند بررسی می‌شود'],2,'او نکتهٔ آخر را خلاصه و دریافت سند را بررسی می‌کند.',{fr:'résume le dernier point et demande aux participants s’ils ont reçu le document',de:'fasst die Leiterin den letzten Punkt zusammen und fragt, ob die Teilnehmenden das Dokument erhalten haben',es:'resume el último punto y pregunta si los participantes han recibido el documento'})],
notes:{fr:n('در موقعیت غیرمنتظره، مسئله و اثر بر مخاطب را روشن کنید؛ زمان موقت بدهید بدون اینکه حل مشکل را قطعی وعده دهید.','La connexion de l’interprète est interrompue.','Nous faisons une pause pendant que l’équipe vérifie la connexion.','اولی شرح اختلال و دومی اقدام فوری است.',[['une pause de cinq minutes','وقفهٔ پنج دقیقه‌ای'],['un plan écrit','طرح مکتوب'],['vérifier la connexion','بررسی اتصال']]),de:n('در اختلال، اثر بر مشارکت‌کنندگان، اقدام فنی و زمان موقت را بیان کنید؛ از وعدهٔ قطعی بدون اطلاع پرهیز کنید.','Die Verbindung der Dolmetscherin ist unterbrochen.','Wir machen eine Pause, während das Team die Verbindung prüft.','اولی شرح اختلال و دومی اقدام فوری است.',[['eine Pause von fünf Minuten','وقفهٔ پنج دقیقه‌ای'],['eine schriftliche Gliederung','طرح مکتوب'],['die Verbindung prüfen','بررسی اتصال']]),es:n('در اختلال، وضعیت و اثر آن را شرح دهید، اقدام و وقفه را بیان کنید و از وعدهٔ حل فوری بدون اطلاع بپرهیزید.','Se ha interrumpido la conexión de la intérprete.','Hacemos una pausa mientras el equipo comprueba la conexión.','اولی شرح اختلال و دومی اقدام فوری است.',[['una pausa de cinco minutos','وقفهٔ پنج دقیقه‌ای'],['un esquema escrito','طرح مکتوب'],['comprobar la conexión','بررسی اتصال']])},
speaking:'در نقش مسئول، اختلال را توضیح دهید، اقدام موقت و زمان را اعلام کنید و پس از بازگشت اتصال موضوع را جمع‌بندی کنید.',writing:'پیامی به شرکت‌کنندگان بنویسید که وضعیت، وقفه، سند جایگزین و اقدام بعدی را بدون وعدهٔ تأییدنشده مشخص کند.',steps:['اختلال و اثر آن بر دسترسی را شرح دهید.','اقدام فوری و زمان بازبینی را اعلام کنید.','دسترسی به طرح مکتوب را توضیح دهید.','برای شروع دوباره خلاصه و دریافت سند را بررسی کنید.'],model:{fr:'La connexion de notre interprète est interrompue, donc certaines personnes ne peuvent plus suivre dans leur langue. L’équipe technique vérifie la connexion et nous faisons une pause de cinq minutes. Pendant ce temps, nous vous enverrons le plan écrit dans les deux langues. Nous vous informerons de la suite après la vérification. À la reprise, nous résumerons le dernier point et confirmerons que chacun a reçu le document.',de:'Die Verbindung unserer Dolmetscherin ist unterbrochen, deshalb können einige Personen nicht mehr in ihrer Sprache folgen. Das technische Team prüft die Verbindung und wir machen fünf Minuten Pause. Währenddessen senden wir die schriftliche Gliederung in beiden Sprachen. Nach der Prüfung informieren wir Sie über das weitere Vorgehen. Beim Neustart fassen wir den letzten Punkt zusammen und prüfen, ob alle das Dokument erhalten haben.',es:'Se ha interrumpido la conexión de nuestra intérprete, por lo que algunas personas no pueden seguir la presentación en su idioma. El equipo técnico está comprobando la conexión y haremos una pausa de cinco minutos. Mientras tanto, enviaremos el esquema escrito en ambos idiomas. Tras la comprobación informaremos de los siguientes pasos. Al reanudar, resumiremos el último punto y confirmaremos la recepción del documento.'}},
{id:'b1-summarize-event',level:'b1',section:'foundation',number:23,title:'خلاصه‌سازی یک اطلاعیه',passage:{
fr:'La bibliothèque du quartier annonce une journée de réparation le samedi 14 juin, de dix heures à seize heures. Les habitants pourront apporter de petits appareils électriques, comme une lampe ou une radio. Des bénévoles examineront les objets avec leurs propriétaires et expliqueront les réparations possibles. Le service est gratuit, mais les pièces nécessaires ne sont pas fournies. Pour participer, il faut réserver une place par téléphone avant le 10 juin. Les objets trop lourds et les appareils contenant du gaz ne seront pas acceptés. La bibliothèque demande aussi aux participants d’apporter le câble de l’appareil et de signaler tout problème connu au moment de la réservation.',
de:'Die Stadtteilbibliothek kündigt für Samstag, den 14. Juni, von zehn bis sechzehn Uhr einen Reparaturtag an. Die Einwohner können kleine Elektrogeräte wie eine Lampe oder ein Radio mitbringen. Freiwillige prüfen die Gegenstände gemeinsam mit ihren Besitzern und erklären mögliche Reparaturen. Der Service ist kostenlos, notwendige Ersatzteile werden aber nicht bereitgestellt. Wer teilnehmen möchte, muss vor dem 10. Juni telefonisch einen Platz reservieren. Zu schwere Gegenstände und Geräte, die Gas enthalten, werden nicht angenommen. Die Bibliothek bittet die Teilnehmenden außerdem, das Kabel mitzubringen und bekannte Probleme bei der Reservierung anzugeben.',
es:'La biblioteca del barrio anuncia un día de reparación el sábado 14 de junio, de diez a dieciséis horas. Los vecinos podrán llevar pequeños aparatos eléctricos, como una lámpara o una radio. Los voluntarios revisarán los objetos con sus propietarios y explicarán las posibles reparaciones. El servicio es gratuito, pero no se proporcionan las piezas necesarias. Para participar hay que reservar una plaza por teléfono antes del 10 de junio. No se aceptarán objetos demasiado pesados ni aparatos que contengan gas. La biblioteca también pide a los participantes que lleven el cable del aparato y comuniquen cualquier problema conocido al hacer la reserva.'},
questions:[q('هدف روز کتابخانه چیست؟',['بررسی و توضیح تعمیر وسایل کوچک','فروش رادیوهای جدید','جمع‌آوری کتاب‌های درسی'],0,'داوطلبان وسایل را بررسی و تعمیرهای ممکن را توضیح می‌دهند.',{fr:'expliqueront les réparations possibles',de:'erklären mögliche Reparaturen',es:'explicarán las posibles reparaciones'}),q('برای شرکت چه باید کرد؟',['بدون ثبت‌نام مراجعه کرد','پیش از ده ژوئن تلفنی جا رزرو کرد','قطعه‌ها را از کتابخانه خرید'],1,'ثبت‌نام تلفنی پیش از ده ژوئن لازم است.',{fr:'réserver une place par téléphone avant le 10 juin',de:'vor dem 10. Juni telefonisch einen Platz reservieren',es:'reservar una plaza por teléfono antes del 10 de junio'}),q('کدام نکته محدودیت خدمت را بیان می‌کند؟',['خدمت فقط برای کتاب‌هاست','هیچ وسیلهٔ برقی پذیرفته نمی‌شود','قطعات لازم ارائه نمی‌شوند'],2,'خدمت رایگان است اما قطعات لازم ارائه نمی‌شوند.',{fr:'les pièces nécessaires ne sont pas fournies',de:'notwendige Ersatzteile werden aber nicht bereitgestellt',es:'no se proporcionan las piezas necesarias'})],
notes:{fr:n('در خلاصه، موضوع، زمان، شرط و محدودیت اصلی را حفظ کنید و جزئیات فرعی را حذف کنید. «En résumé» آغاز جمع‌بندی را نشان می‌دهد.','La bibliothèque organise une journée de réparation.','En résumé, il faut réserver et apporter son appareil.','اولی موضوع و دومی جمع‌بندی دستور اصلی است.',[['réserver une place','رزرو جا'],['des pièces nécessaires','قطعات لازم'],['signaler un problème','گزارش مشکل']]),de:n('برای خلاصه ابتدا موضوع و سپس زمان، شرط شرکت و محدودیت را بگویید؛ «zusammengefasst» جمع‌بندی را معرفی می‌کند.','Die Bibliothek organisiert einen Reparaturtag.','Zusammengefasst muss man einen Platz reservieren und das Gerät mitbringen.','اولی موضوع و دومی جمع‌بندی دستور اصلی است.',[['einen Platz reservieren','رزرو جا'],['notwendige Ersatzteile','قطعات لازم'],['ein Problem angeben','گزارش مشکل']]),es:n('در خلاصه موضوع، زمان، شرط و محدودیت اصلی را نگه دارید و مثال‌های فرعی را حذف کنید؛ «en resumen» جمع‌بندی را آغاز می‌کند.','La biblioteca organiza un día de reparación.','En resumen, hay que reservar y llevar el aparato.','اولی موضوع و دومی جمع‌بندی دستور اصلی است.',[['reservar una plaza','رزرو جا'],['las piezas necesarias','قطعات لازم'],['comunicar un problema','گزارش مشکل']])},
speaking:'اطلاعیه را بدون خواندن جمله به جمله خلاصه کنید و زمان، روش رزرو و محدودیت قطعات را بگویید.',writing:'برای دوستی خلاصه‌ای کوتاه و دقیق از اطلاعیه بنویسید.',steps:['رویداد و زمان آن را مشخص کنید.','روش شرکت و مهلت را بیان کنید.','رایگان بودن و محدودیت قطعات را توضیح دهید.','خلاصه را با متن مقایسه کنید تا چیزی اضافه نشده باشد.'],model:{fr:'La bibliothèque organise une journée de réparation le 14 juin, de dix à seize heures. Des bénévoles examineront de petits appareils avec leurs propriétaires. Le service est gratuit, mais les pièces ne sont pas fournies. Il faut réserver par téléphone avant le 10 juin et apporter le câble.',de:'Die Bibliothek veranstaltet am 14. Juni von zehn bis sechzehn Uhr einen Reparaturtag. Freiwillige prüfen kleine Geräte mit ihren Besitzern. Der Service ist kostenlos, Ersatzteile werden jedoch nicht bereitgestellt. Man muss vor dem 10. Juni telefonisch reservieren und das Kabel mitbringen.',es:'La biblioteca organiza un día de reparación el 14 de junio, de diez a dieciséis horas. Los voluntarios revisarán pequeños aparatos con sus propietarios. El servicio es gratuito, pero no se proporcionan piezas. Hay que reservar por teléfono antes del 10 de junio y llevar el cable.'}},
{id:'b1-coherent-paragraph',level:'b1',section:'foundation',number:25,title:'ساخت پاراگراف منسجم دربارهٔ یک تغییر',passage:{
fr:'Depuis septembre, notre centre de formation ouvre une salle d’étude le soir. Avant ce changement, beaucoup d’apprenants devaient partir juste après les cours parce que la bibliothèque fermait tôt. Maintenant, ils peuvent travailler ensemble jusqu’à vingt heures. Par exemple, notre groupe révise le vocabulaire deux fois par semaine dans cette salle. Cependant, le nombre de places est limité et il faut parfois attendre. Pour améliorer la situation, nous proposons d’afficher les horaires moins fréquentés. Ainsi, chacun pourrait choisir un moment adapté. À mon avis, cette salle est utile, mais une meilleure information aiderait davantage de personnes à en profiter.',
de:'Seit September öffnet unser Bildungszentrum abends einen Lernraum. Vor dieser Änderung mussten viele Lernende direkt nach dem Unterricht gehen, weil die Bibliothek früh schloss. Jetzt können sie bis zwanzig Uhr zusammen arbeiten. Zum Beispiel wiederholt unsere Gruppe zweimal pro Woche in diesem Raum Vokabeln. Allerdings ist die Zahl der Plätze begrenzt und manchmal muss man warten. Um die Situation zu verbessern, schlagen wir vor, weniger frequentierte Zeiten bekannt zu geben. So könnte jeder eine passende Zeit wählen. Meiner Meinung nach ist der Raum nützlich, aber bessere Informationen würden mehr Menschen helfen, ihn zu nutzen.',
es:'Desde septiembre, nuestro centro de formación abre una sala de estudio por la tarde. Antes de este cambio, muchos estudiantes tenían que marcharse justo después de clase porque la biblioteca cerraba temprano. Ahora pueden trabajar juntos hasta las veinte. Por ejemplo, nuestro grupo repasa vocabulario dos veces por semana en esa sala. Sin embargo, el número de plazas es limitado y a veces hay que esperar. Para mejorar la situación, proponemos informar de las horas menos concurridas. Así cada persona podría elegir un momento adecuado. En mi opinión, la sala es útil, pero una mejor información ayudaría a más personas a aprovecharla.'},
questions:[q('تغییر اصلی مرکز چیست؟',['باز شدن اتاق مطالعه در عصر','تعطیلی کلاس‌های زبان','کاهش ساعت کتابخانه'],0,'مرکز اتاق مطالعه را عصر باز می‌کند.',{fr:'ouvre une salle d’étude le soir',de:'öffnet unser Bildungszentrum abends einen Lernraum',es:'abre una sala de estudio por la tarde'}),q('مثال گروه نویسنده چیست؟',['هر روز فیلم می‌بینند','هفته‌ای دو بار واژگان را مرور می‌کنند','در کتابخانه کار می‌کنند'],1,'گروه دو بار در هفته واژگان را مرور می‌کند.',{fr:'révise le vocabulaire deux fois par semaine',de:'wiederholt unsere Gruppe zweimal pro Woche',es:'repasa vocabulario dos veces por semana'}),q('راه پیشنهادی برای مشکل ظرفیت چیست؟',['بستن سالن','حذف کلاس','اطلاع‌رسانی دربارهٔ ساعت‌های خلوت'],2,'نویسنده پیشنهاد می‌کند ساعت‌های خلوت اطلاع‌رسانی شوند.',{fr:'afficher les horaires moins fréquentés',de:'weniger frequentierte Zeiten bekannt zu geben',es:'informar de las horas menos concurridas'})],
notes:{fr:n('یک پاراگراف با ایدهٔ اصلی آغاز می‌شود؛ «par exemple» شاهد و «cependant» محدودیت مرتبط را اضافه می‌کند.','La salle est utile pour étudier.','Cependant, les places sont limitées.','دومی با تضاد به ادعای اول مرتبط است.',[['une salle d’étude','اتاق مطالعه'],['un nombre limité de places','ظرفیت محدود'],['améliorer la situation','بهبود وضعیت']]),de:n('پاراگراف را با موضوع آغاز کنید و برای مثال و محدودیت از «zum Beispiel» و «allerdings» استفاده کنید.','Der Raum ist zum Lernen nützlich.','Allerdings ist die Zahl der Plätze begrenzt.','دومی با تضاد به ادعای اول مرتبط است.',[['ein Lernraum','اتاق مطالعه'],['begrenzte Plätze','ظرفیت محدود'],['die Situation verbessern','بهبود وضعیت']]),es:n('موضوع اصلی را با مثال و سپس محدودیت مرتبط گسترش دهید؛ «por ejemplo» و «sin embargo» نقش جمله‌ها را روشن می‌کنند.','La sala es útil para estudiar.','Sin embargo, las plazas son limitadas.','دومی با تضاد به ادعای اول مرتبط است.',[['una sala de estudio','اتاق مطالعه'],['plazas limitadas','ظرفیت محدود'],['mejorar la situación','بهبود وضعیت']])},
speaking:'دربارهٔ یک تغییر آشنا ایدهٔ اصلی، مثال، محدودیت و راه‌حل مرتبط بیان کنید.',writing:'پاراگرافی منسجم دربارهٔ فضایی برای مطالعه بنویسید که هر جمله به ایدهٔ اصلی مربوط باشد.',steps:['ایدهٔ اصلی را در جملهٔ نخست بنویسید.','یک دلیل و یک مثال مرتبط اضافه کنید.','محدودیت و پیشنهاد بهبود را با رابط روشن بیان کنید.','ارجاع و ارتباط جمله‌ها را بررسی کنید.'],model:{fr:'La salle d’étude du centre est utile aux apprenants. Elle reste ouverte après les cours, ce qui permet de travailler ensemble. Par exemple, notre groupe y révise deux fois par semaine. Cependant, les places sont limitées. Nous proposons donc d’indiquer les horaires moins fréquentés pour aider chacun à choisir son moment.',de:'Der Lernraum des Zentrums ist für die Lernenden nützlich. Er bleibt nach dem Unterricht offen, sodass man zusammen arbeiten kann. Zum Beispiel wiederholt unsere Gruppe dort zweimal pro Woche. Allerdings sind die Plätze begrenzt. Deshalb schlagen wir vor, weniger frequentierte Zeiten bekannt zu geben.',es:'La sala de estudio del centro es útil para los estudiantes. Permanece abierta después de clase, así que podemos trabajar juntos. Por ejemplo, nuestro grupo repasa allí dos veces por semana. Sin embargo, las plazas son limitadas. Por eso proponemos informar de las horas menos concurridas.'}},
{id:'b1-decision-consequences',level:'b1',section:'survival',number:20,title:'علت و پیامد تصمیم گروه',passage:{
fr:'Un groupe de voisins voulait organiser un repas dans le jardin commun samedi. Comme la météo annonçait de fortes pluies, ils ont décidé de déplacer le repas dans la salle du quartier. La salle était plus petite, donc ils ont limité le nombre de participants à trente. Ils ont également demandé à chacun de confirmer sa présence avant jeudi. Certains voisins étaient déçus de ne pas être dans le jardin, mais ils ont apprécié de pouvoir maintenir la rencontre. Après le repas, le groupe a constaté que la salle était facile d’accès. Pour la prochaine fois, il cherchera une salle plus grande ou choisira une date avec une solution de repli.',
de:'Eine Nachbarschaftsgruppe wollte am Samstag ein Essen im gemeinsamen Garten organisieren. Weil der Wetterbericht starken Regen ankündigte, entschied sie, das Essen in den Stadtteilraum zu verlegen. Der Raum war kleiner, deshalb begrenzte die Gruppe die Teilnehmerzahl auf dreißig. Außerdem bat sie alle, ihre Teilnahme vor Donnerstag zu bestätigen. Einige Nachbarn waren enttäuscht, dass das Essen nicht im Garten stattfand, freuten sich aber, dass das Treffen stattfinden konnte. Nach dem Essen stellte die Gruppe fest, dass der Raum gut erreichbar war. Für das nächste Mal sucht sie einen größeren Raum oder wählt einen Termin mit einer Ausweichmöglichkeit.',
es:'Un grupo de vecinos quería organizar una comida en el jardín común el sábado. Como el pronóstico anunciaba lluvias fuertes, decidieron trasladar la comida a la sala del barrio. La sala era más pequeña, por eso limitaron el número de participantes a treinta. También pidieron a todos que confirmaran su asistencia antes del jueves. Algunos vecinos estaban decepcionados por no estar en el jardín, pero valoraron poder mantener el encuentro. Después de la comida, el grupo observó que la sala era fácil de acceder. Para la próxima vez buscará una sala más grande o elegirá una fecha con una alternativa.'},
questions:[q('چرا گروه محل غذا را تغییر داد؟',['پیش‌بینی باران شدید','بسته بودن باغ در تابستان','درخواست صاحب رستوران'],0,'پیش‌بینی باران شدید علت تغییر بود.',{fr:'la météo annonçait de fortes pluies',de:'der Wetterbericht starken Regen ankündigte',es:'el pronóstico anunciaba lluvias fuertes'}),q('پیامد کوچک‌تر بودن سالن چه بود؟',['لغو دیدار','محدود شدن شرکت‌کنندگان به سی نفر','افزایش شرکت‌کنندگان'],1,'به دلیل کوچک‌تر بودن سالن تعداد به سی نفر محدود شد.',{fr:'ils ont limité le nombre de participants à trente',de:'begrenzte die Gruppe die Teilnehmerzahl auf dreißig',es:'limitaron el número de participantes a treinta'}),q('گروه برای دفعهٔ بعد چه می‌کند؟',['بدون برنامه همان شرایط را تکرار می‌کند','فقط در فضای باز برنامه می‌گذارد','سالن بزرگ‌تر یا گزینهٔ جایگزین پیدا می‌کند'],2,'گروه سالن بزرگ‌تر یا تاریخ همراه گزینهٔ جایگزین را در نظر می‌گیرد.',{fr:'une salle plus grande ou choisira une date avec une solution de repli',de:'einen größeren Raum oder wählt einen Termin mit einer Ausweichmöglichkeit',es:'una sala más grande o elegirá una fecha con una alternativa'})],
notes:{fr:n('«comme» یا «parce que» علت و «donc» پیامد را بیان می‌کند؛ علت تغییر مکان را از پیامد محدودیت ظرفیت جدا کنید.','Comme la pluie était prévue, nous avons changé de lieu.','La salle était petite, donc nous avons limité les places.','اولی علت تصمیم و دومی پیامد ظرفیت است.',[['prévoir de la pluie','پیش‌بینی باران'],['limiter les participants','محدود کردن شرکت‌کنندگان'],['une solution de repli','راه‌حل جایگزین']]),de:n('«weil» علت را در جملهٔ وابسته با فعل پایانی بیان می‌کند؛ «deshalb» پیامد را در جملهٔ اصلی نشان می‌دهد.','Weil Regen angekündigt war, änderten wir den Ort.','Der Raum war klein, deshalb begrenzten wir die Plätze.','اولی علت تصمیم و دومی پیامد ظرفیت است.',[['Regen ankündigen','پیش‌بینی باران'],['die Teilnehmerzahl begrenzen','محدود کردن شرکت‌کنندگان'],['eine Ausweichmöglichkeit','راه‌حل جایگزین']]),es:n('«como» در آغاز جمله علت و «por eso» پیامد را معرفی می‌کند؛ میان دلیل تصمیم و نتیجهٔ آن تفاوت بگذارید.','Como se anunciaba lluvia, cambiamos de lugar.','La sala era pequeña, por eso limitamos las plazas.','اولی علت تصمیم و دومی پیامد ظرفیت است.',[['anunciar lluvia','پیش‌بینی باران'],['limitar los participantes','محدود کردن شرکت‌کنندگان'],['una alternativa','راه‌حل جایگزین']])},
speaking:'تصمیم گروه را با علت، دو پیامد و ایده‌ای برای دفعهٔ بعد توضیح دهید.',writing:'پیامی برای همسایه‌ای غایب بنویسید و علت تغییر محل و پیامدهای آن را شرح دهید.',steps:['برنامهٔ اصلی و علت تغییر را معرفی کنید.','تصمیم و محدودیت ظرفیت را توضیح دهید.','واکنش همسایه‌ها را اضافه کنید.','برنامهٔ احتمالی بعدی را بیان کنید.'],model:{fr:'Nous voulions manger dans le jardin samedi, mais nous avons choisi la salle du quartier parce que de fortes pluies étaient annoncées. Comme la salle était plus petite, nous avons limité les places à trente et demandé une confirmation avant jeudi. Certains étaient déçus, mais la rencontre a pu avoir lieu. La prochaine fois, nous chercherons une salle plus grande ou une solution de repli.',de:'Wir wollten am Samstag im Garten essen, aber wegen des angekündigten starken Regens haben wir den Stadtteilraum gewählt. Weil der Raum kleiner war, haben wir die Plätze auf dreißig begrenzt und um Bestätigung vor Donnerstag gebeten. Einige waren enttäuscht, aber das Treffen konnte stattfinden. Beim nächsten Mal suchen wir einen größeren Raum oder eine Ausweichmöglichkeit.',es:'Queríamos comer en el jardín el sábado, pero elegimos la sala del barrio porque se anunciaban lluvias fuertes. Como la sala era más pequeña, limitamos las plazas a treinta y pedimos confirmación antes del jueves. Algunos estaban decepcionados, pero el encuentro pudo celebrarse. La próxima vez buscaremos una sala más grande o una alternativa.'}},
{id:'b1-polite-probability',level:'b1',section:'foundation',number:17,title:'درخواست مؤدبانه و احتمال',passage:{
fr:'Lina doit rendre un dossier vendredi, mais elle attend encore un document de son collègue. Elle lui écrit : « Pourrais-tu me l’envoyer demain matin ? Cela me laisserait le temps de vérifier les chiffres. » Son collègue répond qu’il pourrait l’envoyer avant midi, mais qu’il doit d’abord recevoir une confirmation du service financier. Si cette confirmation arrive tard, le document pourrait être prêt seulement en fin de journée. Lina remercie son collègue et propose de commencer la vérification des autres parties en attendant. Ils conviennent de se parler jeudi après-midi si le document n’est pas arrivé.',
de:'Lina muss am Freitag einen Bericht abgeben, wartet aber noch auf ein Dokument ihres Kollegen. Sie schreibt ihm: „Könntest du es mir morgen früh schicken? Das würde mir Zeit geben, die Zahlen zu prüfen.“ Ihr Kollege antwortet, dass er es gestern nicht fertigstellen konnte und zuerst eine Bestätigung der Finanzabteilung erhalten muss. Er sagt: „Die Bestätigung muss schon unterwegs sein, aber ich weiß es nicht sicher.“ Er könnte das Dokument vor Mittag schicken. Wenn diese Bestätigung spät kommt, könnte das Dokument erst am Ende des Tages fertig sein. Lina bedankt sich und schlägt vor, inzwischen die anderen Teile zu prüfen. Sie vereinbaren, am Donnerstagnachmittag miteinander zu sprechen, falls das Dokument nicht angekommen ist.',
es:'Lina tiene que entregar un informe el viernes, pero todavía espera un documento de su compañero. Le escribe: «¿Podrías enviármelo mañana por la mañana? Eso me daría tiempo para revisar las cifras». Su compañero responde que ayer no pudo terminarlo y que primero debe recibir una confirmación del departamento financiero. Dice: «La confirmación debe de estar en camino, pero no lo sé con seguridad». Podría enviar el documento antes del mediodía. Si esa confirmación llega tarde, el documento podría estar listo solo al final del día. Lina le da las gracias y propone empezar a revisar las otras partes mientras espera. Acuerdan hablar el jueves por la tarde si el documento no ha llegado.'},
questions:[q('لینا چه درخواستی دارد؟',['ارسال سند صبح فردا','تغییر موعد گزارش به ماه بعد','حذف اطلاعات مالی'],0,'او می‌خواهد سند صبح فردا ارسال شود.',{fr:'Pourrais-tu me l’envoyer demain matin',de:'Könntest du es mir morgen früh schicken',es:'¿Podrías enviármelo mañana por la mañana'}),q('ارسال پیش از ظهر به چه چیزی وابسته است؟',['خرید رایانهٔ تازه','دریافت تأیید واحد مالی','تعطیل شدن دفتر'],1,'همکار ابتدا باید تأیید واحد مالی را دریافت کند.',{fr:'recevoir une confirmation du service financier',de:'eine Bestätigung der Finanzabteilung erhalten',es:'recibir una confirmación del departamento financiero'}),q('اگر سند نرسد چه توافقی دارند؟',['گزارش را بدون بررسی می‌فرستند','تا جمعه صحبت نمی‌کنند','پنجشنبه بعدازظهر صحبت می‌کنند'],2,'اگر سند نرسد پنجشنبه بعدازظهر صحبت خواهند کرد.',{fr:'se parler jeudi après-midi si le document n’est pas arrivé',de:'am Donnerstagnachmittag miteinander zu sprechen, falls das Dokument nicht angekommen ist',es:'hablar el jueves por la tarde si el documento no ha llegado'})],
notes:{fr:n('Conditionnel présent می‌تواند درخواست را مؤدبانه یا نتیجه را محتمل بیان کند؛ امکان به معنای قطعیت نیست.','Pourrais-tu envoyer le document ?','Le document pourrait être prêt ce soir.','اولی درخواست مؤدبانه و دومی احتمال است.',[['envoyer un document','فرستادن سند'],['vérifier les chiffres','بررسی ارقام'],['attendre une confirmation','منتظر تأیید بودن']]),de:n('افعال وجهی در گذشته مانند «konnte» توانایی گذشته را بیان می‌کنند. «muss … sein» می‌تواند استنباط قوی باشد، نه الزام؛ «könnte» امکان را نشان می‌دهد.','Gestern konnte er das Dokument nicht fertigstellen.','Die Bestätigung muss schon unterwegs sein.','اولی ناتوانی در گذشته و دومی استنباط قوی، نه واقعیت قطعی است.',[['ein Dokument schicken','فرستادن سند'],['die Zahlen prüfen','بررسی ارقام'],['auf eine Bestätigung warten','منتظر تأیید بودن']]),es:n('«no pudo» ناتوانی گذشته و «debe de» استنباط احتمالی را نشان می‌دهد؛ «podría» نیز امکان را بدون وعدهٔ قطعی بیان می‌کند.','Ayer no pudo terminar el documento.','La confirmación debe de estar en camino.','اولی ناتوانی گذشته و دومی استنباط است، نه واقعیت قطعی.',[['enviar un documento','فرستادن سند'],['revisar las cifras','بررسی ارقام'],['esperar una confirmación','منتظر تأیید بودن']])},
speaking:'از همکار فرضی سندی مؤدبانه بخواهید و احتمال تأخیر و اقدام جایگزین را بیان کنید.',writing:'پیامی بنویسید که درخواست، دلیل، احتمال و زمان پیگیری را مشخص کند.',steps:['مهلت و نیاز خود را توضیح دهید.','با ساختار مؤدبانه سند را درخواست کنید.','احتمال تأخیر را بدون قطعیت بیان کنید.','زمان پیگیری و کار جایگزین را پیشنهاد دهید.'],model:{fr:'Bonjour, pourrais-tu m’envoyer le document demain matin ? Je dois rendre le dossier vendredi et cela me donnerait le temps de vérifier les chiffres. Je comprends que la confirmation pourrait arriver tard. En attendant, je vérifierai les autres parties. Si nécessaire, nous pourrons en parler jeudi après-midi. Merci !',de:'Hallo, könntest du mir das Dokument morgen früh schicken? Ich muss den Bericht am Freitag abgeben und hätte dann Zeit, die Zahlen zu prüfen. Ich verstehe, dass die Bestätigung spät kommen könnte. Inzwischen prüfe ich die anderen Teile. Falls nötig, sprechen wir am Donnerstagnachmittag. Danke!',es:'Hola, ¿podrías enviarme el documento mañana por la mañana? Tengo que entregar el informe el viernes y así tendría tiempo de revisar las cifras. Entiendo que la confirmación podría llegar tarde. Mientras tanto revisaré las otras partes. Si hace falta, hablamos el jueves por la tarde. ¡Gracias!'}},
{id:'b2-preference-uncertainty',level:'b2',section:'foundation',number:18,title:'ترجیح، تردید و درجهٔ اطمینان',passage:{
fr:'Le comité d’une école examine deux façons d’informer les familles : une lettre imprimée chaque mois ou une plateforme numérique. Nora préférerait la plateforme, car elle permettrait de corriger rapidement les informations. Elle doute néanmoins que toutes les familles puissent y accéder facilement. Malik estime qu’une lettre serait plus accessible pour certaines personnes, mais il n’est pas certain que la distribution mensuelle suffise en cas de changement urgent. Les deux membres jugent probable qu’une combinaison des deux moyens soit utile, sans connaître encore son coût. Ils décident de demander aux familles quels supports elles utilisent et d’obtenir une estimation avant de choisir.',
de:'Das Gremium einer Schule prüft zwei Möglichkeiten, Familien zu informieren: einen monatlichen gedruckten Brief oder eine digitale Plattform. Nora würde die Plattform bevorzugen, weil Informationen dort schnell korrigiert werden könnten. Sie bezweifelt jedoch, dass alle Familien leicht darauf zugreifen können. Malik meint, ein Brief wäre für manche Menschen zugänglicher, ist aber nicht sicher, ob eine monatliche Verteilung bei dringenden Änderungen ausreicht. Beide halten es für wahrscheinlich, dass eine Kombination der beiden Wege nützlich wäre, kennen aber ihre Kosten noch nicht. Sie beschließen, die Familien nach ihren genutzten Medien zu fragen und vor der Entscheidung eine Kostenschätzung einzuholen.',
es:'El comité de una escuela estudia dos formas de informar a las familias: una carta impresa mensual o una plataforma digital. Nora preferiría la plataforma porque permitiría corregir rápidamente la información. Sin embargo, duda que todas las familias puedan acceder a ella fácilmente. Malik considera que una carta sería más accesible para algunas personas, pero no está seguro de que una distribución mensual sea suficiente ante un cambio urgente. Ambos creen probable que una combinación de los dos medios sea útil, aunque todavía no conocen su coste. Deciden preguntar a las familias qué medios utilizan y obtener una estimación antes de elegir.'},
questions:[q('نورا کدام گزینه را ترجیح می‌دهد و چرا؟',['پلتفرم، به دلیل امکان اصلاح سریع','نامه، به دلیل ارسال فوری روزانه','حذف تمام اطلاع‌رسانی'],0,'نورا پلتفرم را برای امکان اصلاح سریع ترجیح می‌دهد.',{fr:'Nora préférerait la plateforme, car elle permettrait de corriger rapidement',de:'Nora würde die Plattform bevorzugen, weil Informationen dort schnell korrigiert werden könnten',es:'Nora preferiría la plataforma porque permitiría corregir rápidamente'}),q('مالک دربارهٔ نامهٔ ماهانه در چه موردی مطمئن نیست؟',['وجود مدرسه','کافی بودن آن برای تغییر فوری','قابل چاپ بودن نامه'],1,'او از کافی بودن توزیع ماهانه برای تغییر فوری مطمئن نیست.',{fr:'n’est pas certain que la distribution mensuelle suffise en cas de changement urgent',de:'nicht sicher, ob eine monatliche Verteilung bei dringenden Änderungen ausreicht',es:'no está seguro de que una distribución mensual sea suficiente ante un cambio urgente'}),q('پیش از انتخاب چه چیزی را بررسی می‌کنند؟',['فقط رنگ نامه','تعداد مدارس شهر','روش مورد استفادهٔ خانواده‌ها و برآورد هزینه'],2,'از خانواده‌ها می‌پرسند و برآورد هزینه می‌گیرند.',{fr:'demander aux familles quels supports elles utilisent et d’obtenir une estimation',de:'die Familien nach ihren genutzten Medien zu fragen und vor der Entscheidung eine Kostenschätzung einzuholen',es:'preguntar a las familias qué medios utilizan y obtener una estimación'})],
notes:{fr:n('برای تمایز ترجیح، تردید و احتمال از «je préférerais»، «je doute que» با subjonctif و «il est probable que» استفاده کنید؛ آنها قطعیت یکسانی ندارند.','Je préférerais une plateforme.','Je doute que toutes les familles puissent y accéder.','اولی ترجیح است؛ دومی تردید دربارهٔ دسترسی.',[['un support numérique','رسانهٔ دیجیتال'],['une estimation des coûts','برآورد هزینه'],['un changement urgent','تغییر فوری']]),de:n('«ich würde … bevorzugen» ترجیح و «ich bezweifle, dass …» تردید را بیان می‌کند؛ «wahrscheinlich» احتمال را از اطمینان جدا می‌کند.','Ich würde eine Plattform bevorzugen.','Ich bezweifle, dass alle Familien darauf zugreifen können.','اولی ترجیح است؛ دومی تردید دربارهٔ دسترسی.',[['ein digitales Medium','رسانهٔ دیجیتال'],['eine Kostenschätzung','برآورد هزینه'],['eine dringende Änderung','تغییر فوری']]),es:n('«preferiría» ترجیح و «dudo que» با subjuntivo تردید را بیان می‌کند؛ «es probable que» نیز امکان را با درجه‌ای از احتمال مطرح می‌کند.','Preferiría una plataforma.','Dudo que todas las familias puedan acceder a ella.','اولی ترجیح است؛ دومی تردید دربارهٔ دسترسی.',[['un medio digital','رسانهٔ دیجیتال'],['una estimación de costes','برآورد هزینه'],['un cambio urgente','تغییر فوری']])},
speaking:'دو روش اطلاع‌رسانی را مقایسه کنید، ترجیح خود، یک تردید و اطلاعات موردنیاز برای تصمیم را با درجهٔ اطمینان بیان کنید.',writing:'یادداشت کوتاهی به کمیته بنویسید که ترجیح، تردید، احتمال و روش بررسی را جدا کند.',steps:['دو گزینه و ترجیح خود را معرفی کنید.','یک تردید و دلیل آن را توضیح دهید.','امکان ترکیب را بدون قطعیت مطرح کنید.','پرسش از خانواده‌ها و برآورد هزینه را پیشنهاد دهید.'],model:{fr:'Je préférerais une plateforme parce qu’elle permettrait de corriger les informations rapidement. Je doute cependant que toutes les familles puissent y accéder facilement. Une lettre mensuelle ne suffirait peut-être pas en cas d’urgence. Il est probable qu’une combinaison soit utile, mais nous ne connaissons pas encore son coût. Demandons aux familles quels supports elles utilisent et obtenons une estimation avant de décider.',de:'Ich würde eine Plattform bevorzugen, weil Informationen schnell korrigiert werden könnten. Ich bezweifle jedoch, dass alle Familien leicht darauf zugreifen können. Ein monatlicher Brief reicht bei dringenden Änderungen möglicherweise nicht aus. Wahrscheinlich wäre eine Kombination hilfreich, aber ihre Kosten kennen wir noch nicht. Wir sollten die Familien nach ihren Medien fragen und vor der Entscheidung eine Kostenschätzung einholen.',es:'Preferiría una plataforma porque permitiría corregir rápidamente la información. Sin embargo, dudo que todas las familias puedan acceder a ella fácilmente. Una carta mensual quizá no sea suficiente ante un cambio urgente. Es probable que una combinación sea útil, pero todavía desconocemos su coste. Preguntemos a las familias qué medios utilizan y obtengamos una estimación antes de decidir.'}},
];
